	private static final IRI CREATED_IRI = SimpleValueFactory.getInstance().createIRI("urn:test:created");

	@Test
	void everyAsciiInsertionSubstitutionDeletionAndTruncationMatchesReference() {
		ProbeParser cold = new ProbeParser();
		ProbeParser reused = new ProbeParser();
		warm(reused);
		int cases = 0;
		for (String seed : List.of("http://a/b?c#d", "https://x:80/a%20b?c#d", "http://1.2.3.4/a",
				"http://u@h/a", "urn:x:y?z#f", "https://a", "urn:", "http://[::1]/a")) {
			for (int offset = 0; offset <= seed.length(); offset++) {
				for (char ascii = 0; ascii < 128; ascii++) {
					assertColdAndReused(cold, reused, seed.substring(0, offset) + ascii + seed.substring(offset));
					cases++;
					if (offset < seed.length()) {
						assertColdAndReused(cold, reused,
								seed.substring(0, offset) + ascii + seed.substring(offset + 1));
						cases++;
					}
				}
				assertColdAndReused(cold, reused, seed.substring(0, offset));
				assertColdAndReused(cold, reused, seed.substring(offset));
				cases += 2;
				if (offset < seed.length()) {
					assertColdAndReused(cold, reused, seed.substring(0, offset) + seed.substring(offset + 1));
					cases++;
				}
			}
		}
		// A bounded deterministic corpus, checked once cold and once on a continuously reused parser.
		assertEquals(27_458, cases);
	}

	@Test
	void percentEncodedBytesAndMalformedPairsMatchInEveryComponent() {
		ProbeParser cold = new ProbeParser();
		ProbeParser reused = new ProbeParser();
		warm(reused);
		for (String template : List.of("http://a%s.example/p", "http://u%sv@host/p", "http://host/a%sb",
				"https://host/p?a%sb", "https://host/p#a%sb", "urn:example:a%sb")) {
			for (int value = 0; value <= 255; value++) {
				String encoded = String.format(Locale.ROOT, "%%%02X", value);
				assertColdAndReused(cold, reused, template.replace("%s", encoded));
				assertColdAndReused(cold, reused, template.replace("%s", encoded.toLowerCase(Locale.ROOT)));
			}
			for (char ascii = 0; ascii < 128; ascii++) {
				assertColdAndReused(cold, reused, template.replace("%s", "%" + ascii + "0"));
				assertColdAndReused(cold, reused, template.replace("%s", "%0" + ascii));
			}
			for (String encoded : List.of("%", "%0", "%GG", "%+1", "%-1", "%\u0660\u0661", "%\uFF26\uFF26",
					"%2/", "%2?", "%2#", "%%00", "%00%FF", "%C3%A9", "%ED%A0%80")) {
				assertColdAndReused(cold, reused, template.replace("%s", encoded));
			}
		}
	}

