	@Test
	void emptySignedLongAndOverflowingPortsKeepExactOutcomes() {
		ProbeParser cold = new ProbeParser();
		ProbeParser reused = new ProbeParser();
		warm(reused);
		for (String port : List.of("", "0", "00", "80", "65535", "65536", "999999999", "1000000000", "0000000000",
				"2147483647", "2147483648",
				"9999999999", "00000000000000000000000000000000000000000000000080", "0".repeat(300),
				"9".repeat(300), "+1", "-1", "-0", "1a", "1:2", "%38%30", "\uFF18\uFF10", "\u0668\u0660")) {
			for (String host : List.of("example.org", "1.2.3.4", "[::1]")) {
				for (String suffix : List.of("", "/p", "?q", "#f", "/p@tail", "?q@tail")) {
					assertColdAndReused(cold, reused, "http://" + host + ":" + port + suffix);
				}
			}
		}
		// Pin the unchecked exception explicitly as well as comparing it in the differential corpus.
		String overflowing = "http://example.org:2147483648/p";
		NumberFormatException expected = assertThrows(NumberFormatException.class, () -> new ParsedIRI(overflowing));
		reused.listener.clear();
		int calls = reused.factory.calls;
		NumberFormatException actual = assertThrows(NumberFormatException.class, () -> reused.iri(overflowing));
		assertEquals(expected.getMessage(), actual.getMessage());
		assertEquals(calls, reused.factory.calls);
		assertNoDiagnostics(reused, () -> overflowing);
	}

