	@Test
	void repeatedCollidingLongAndBackoffInputsStillCallFactoryForEveryOccurrence() {
		ProbeParser parser = new ProbeParser();
		for (String value : List.of("http://example.org/p", "https://example.org/p?q#f", "urn:example:item",
				"HTTP://example.org/p", "relative/path", "http://example.org/\u00E9", "http://example.org:80/p")) {
			parser.reset();
			for (int i = 0; i < 192; i++) {
				assertMatchesReference(parser, new String(value.toCharArray()));
			}
		}
		String collisionA = "http://example.org/Aa";
		String collisionB = "http://example.org/BB";
		assertEquals(collisionA.hashCode(), collisionB.hashCode());
		for (int i = 0; i < 192; i++) {
			assertMatchesReference(parser, (i & 1) == 0 ? collisionA : collisionB);
		}
		for (int length : List.of(255, 256, 257, 4096)) {
			String value = "http://example.org/" + "x".repeat(length - "http://example.org/".length());
			for (int i = 0; i < 4; i++) {
				assertMatchesReference(parser, value);
				assertMatchesReference(parser, value + "#one#two");
			}
		}
		parser.reset();
		// Exceed both the initial trial and the 1024-validation backoff, then allow repeated input to warm again.
		for (int i = 0; i < 1400; i++) {
			assertMatchesReference(parser, "http://example.org/unique/" + i);
		}
		for (int i = 0; i < 1200; i++) {
			assertMatchesReference(parser, "http://example.org/repeated");
		}
		assertMatchesReference(parser, "http://example.org/invalid%0");
		parser.reset();
		assertMatchesReference(parser, "http://example.org/repeated");
		assertMatchesReference(parser, "http://example.org/invalid%0");
	}

