	@Test
	void disablingAndReenablingValidationPreservesFactoryArgumentsAndErrors() {
		ProbeParser parser = new ProbeParser();
		warm(parser);
		String[] values = { "http://example.org/p", "urn:example:item", "relative", "http://example.org/%",
				"http://example.org/a b", "http://example.org:2147483648/", "http://example.org/\uD800", null };
		for (int pass = 0; pass < 2; pass++) {
			parser.getParserConfig().set(BasicParserSettings.VERIFY_URI_SYNTAX, false);
			for (String value : values) {
				parser.listener.clear();
				int calls = parser.factory.calls;
				assertSame(CREATED_IRI, parser.iri(value));
				assertEquals(calls + 1, parser.factory.calls);
				assertSame(value, parser.factory.lastInput);
				assertNoDiagnostics(parser, () -> printable(value));
			}
			parser.getParserConfig().set(BasicParserSettings.VERIFY_URI_SYNTAX, true);
			for (String value : values) {
				assertMatchesReference(parser, value);
			}
			parser.reset();
		}
	}

	@Test
	void warmedValidationDoesNotHideFactoryFailuresOrReplacement() {
		ProbeParser parser = new ProbeParser();
		warm(parser);
		RuntimeException failure = new IllegalArgumentException("factory rejected this occurrence");
		parser.factory.failure = failure;
		parser.listener.clear();
		int calls = parser.factory.calls;
		RDFParseException actual = assertThrows(RDFParseException.class,
				() -> parser.iri("http://example.org/warm"));
		assertSame(failure, actual.getCause());
		assertEquals(failure.getMessage(), actual.getMessage());
		assertEquals(calls + 1, parser.factory.calls);
		assertEquals(List.of(new Diagnostic(failure.getMessage(), -1, -1)), parser.listener.fatalErrors);
		assertEquals(List.of(), parser.listener.errors);
		assertEquals(List.of(), parser.listener.warnings);
		RecordingValueFactory replacement = new RecordingValueFactory();
		parser.setValueFactory(replacement);
		assertSame(CREATED_IRI, parser.iri("http://example.org/warm"));
		assertEquals(1, replacement.calls);
		assertEquals(calls + 1, parser.factory.calls);
	}

	private static void assertColdAndReused(ProbeParser cold, ProbeParser reused, String value) {
		cold.reset();
		Throwable expected = referenceFailure(value);
		assertMatchesReference(cold, value, expected);
		assertMatchesReference(reused, value, expected);
	}

	private static void assertMatchesReference(ProbeParser parser, String value) {
		assertMatchesReference(parser, value, referenceFailure(value));
	}

	private static Throwable referenceFailure(String value) {
		try {
			new ParsedIRI(value);
			return null;
		} catch (URISyntaxException | RuntimeException | AssertionError failure) {
			return failure;
		}
	}

	private static void assertMatchesReference(ProbeParser parser, String value, Throwable expected) {
		Supplier<String> context = () -> "IRI: " + printable(value);
		int calls = parser.factory.calls;
		parser.listener.clear();
		if (expected == null) {
			assertSame(CREATED_IRI, parser.iri(value), context);
			assertEquals(calls + 1, parser.factory.calls, context);
			assertSame(value, parser.factory.lastInput, context);
			assertNoDiagnostics(parser, context);
		} else if (expected instanceof URISyntaxException) {
			if (parser.getParserConfig().isNonFatalError(BasicParserSettings.VERIFY_URI_SYNTAX)) {
				assertNull(parser.iri(value), context);
			} else {
				RDFParseException actual = assertThrows(RDFParseException.class, () -> parser.iri(value), context);
				assertEquals(RDFParseException.class, actual.getClass(), context);
				assertEquals(expected.getMessage(), actual.getMessage(), context);
				assertNull(actual.getCause(), context);
				assertEquals(-1, actual.getLineNumber(), context);
				assertEquals(-1, actual.getColumnNumber(), context);
			}
			assertEquals(calls, parser.factory.calls, context);
			assertEquals(List.of(new Diagnostic(expected.getMessage(), -1, -1)), parser.listener.errors, context);
			assertEquals(List.of(), parser.listener.warnings, context);
			assertEquals(List.of(), parser.listener.fatalErrors, context);
		} else {
			Throwable actual = assertThrows(expected.getClass(), () -> parser.iri(value), context);
			assertEquals(expected.getClass(), actual.getClass(), context);
			assertEquals(expected.getMessage(), actual.getMessage(), context);
			assertEquals(calls, parser.factory.calls, context);
			assertNoDiagnostics(parser, context);
		}
	}

	private static void assertNoDiagnostics(ProbeParser parser, Supplier<String> context) {
		assertEquals(List.of(), parser.listener.errors, context);
		assertEquals(List.of(), parser.listener.warnings, context);
		assertEquals(List.of(), parser.listener.fatalErrors, context);
	}

	private static void warm(ProbeParser parser) {
		for (int i = 0; i < 192; i++) {
			assertMatchesReference(parser, "http://example.org/warm");
		}
	}

	private static String printable(String value) {
		if (value == null) {
			return "<null>";
		}
		StringBuilder result = new StringBuilder();
		for (int i = 0; i < value.length(); i++) {
			char character = value.charAt(i);
			if (character >= 0x20 && character <= 0x7E && character != '\\') {
				result.append(character);
			} else {
				result.append(String.format(Locale.ROOT, "\\u%04X", (int) character));
			}
		}
		return result.toString();
	}

	private record Diagnostic(String message, long line, long column) {
	}

	private static final class RecordingErrorListener implements ParseErrorListener {
		private final List<Diagnostic> warnings = new ArrayList<>();
		private final List<Diagnostic> errors = new ArrayList<>();
		private final List<Diagnostic> fatalErrors = new ArrayList<>();

		@Override
		public void warning(String message, long line, long column) {
			warnings.add(new Diagnostic(message, line, column));
		}

		@Override
		public void error(String message, long line, long column) {
			errors.add(new Diagnostic(message, line, column));
		}

		@Override
		public void fatalError(String message, long line, long column) {
			fatalErrors.add(new Diagnostic(message, line, column));
		}

		private void clear() {
			warnings.clear();
			errors.clear();
			fatalErrors.clear();
		}
	}

	private static final class RecordingValueFactory extends SimpleValueFactory {
		private int calls;
		private String lastInput;
		private RuntimeException failure;

		@Override
		public IRI createIRI(String value) {
			calls++;
			lastInput = value;
			if (failure != null) {
				throw failure;
			}
			return CREATED_IRI;
		}
	}

	private static final class ProbeParser extends AbstractRDFParser {
		private final RecordingValueFactory factory;
		private final RecordingErrorListener listener = new RecordingErrorListener();

		private ProbeParser() {
			this(new RecordingValueFactory());
		}

		private ProbeParser(RecordingValueFactory factory) {
			super(factory);
			this.factory = factory;
			getParserConfig().set(BasicParserSettings.VERIFY_URI_SYNTAX, true);
			getParserConfig().set(BasicParserSettings.PROCESS_ENCODED_TRIPLE_TERMS, false);
			setParseErrorListener(listener);
		}

		private IRI iri(String value) {
			return createURI(value);
		}

		private void reset() {
			clear();
		}

		@Override
		public RDFFormat getRDFFormat() {
			return RDFFormat.NQUADS;
		}

		@Override
		public void parse(InputStream input, String baseURI) {
			throw new UnsupportedOperationException();
		}

		@Override
		public void parse(Reader reader, String baseURI) {
			throw new UnsupportedOperationException();
		}
	}
